{ $ A=\left\{ x \in \mathbb{N} \mid  x \le 15 \right\} $ }
   { $ A=\left\{ x \in \mathbb{N} \mid  x \ge 15 \right\} $ }
     { $ A=\left\{ x \in \mathbb{N}  \mid 1 \le x \le 15 \right\} $ }
    { \True $ A=\left\{ x \in \mathbb{N} \mid 10 \le x \le 15 \right\} $ }
\loigiai{
Tập $A$ gồm các số tự nhiên liên tiếp từ $10$ đến $15$, nên $A = \{x \in \mathbb{N} \mid 10 \le x \le 15\}$.
}\end{ex}

